import XCTest

final class MenuUITests: XCTestCase {
    func testOpenBlueskyNavigationMenu() {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.launch()
        let buttons = app.buttons.allElementsBoundByIndex.map { "\($0.label) @ \($0.frame)" }.joined(separator: "\n")
        XCTAssertTrue(false, "FRAME=\(app.frame)\nBUTTONS=\n\(buttons)\nTREE=\(app.debugDescription)")
    }
}
EOF
xcodebuild test -project BlueskyMenuAutomation.xcodeproj -scheme MenuUITests -destination 'platform=iOS Simulator,id=99861274-A6B2-4BCA-A984-AC1D6154E713' -derivedDataPath DerivedData CODE_SIGNING_ALLOWED=NO

